-- ===================================================================================================
-- Part 2 — hand-written objects
-- ===================================================================================================

-- appointment (Arch 11.13, 12.1)
ALTER TABLE "appointment" ADD CONSTRAINT "appointment_range_check" CHECK (end_at > start_at);
ALTER TABLE "appointment" ADD CONSTRAINT "appointment_pending_check" CHECK (status <> 'PENDING' OR (hold_expires_at IS NOT NULL AND reservation_secret_hash IS NOT NULL));
ALTER TABLE "appointment" ADD CONSTRAINT "appointment_confirmed_check" CHECK (status IN ('PENDING', 'EXPIRED', 'CANCELLED') OR (patient_id IS NOT NULL AND booking_reference IS NOT NULL));
ALTER TABLE "appointment" ADD CONSTRAINT "appointment_reference_format_check" CHECK (booking_reference IS NULL OR booking_reference ~ '^SC-[0-9A-HJKMNP-TV-Z]{8}$');
-- ADR-006: no overlapping active appointments per doctor (half-open ranges allow back-to-back, BR-053).
ALTER TABLE "appointment" ADD CONSTRAINT "appointment_no_overlap"
  EXCLUDE USING gist (doctor_id WITH =, tstzrange(start_at, end_at, '[)') WITH &&)
  WHERE (status IN ('PENDING', 'CONFIRMED', 'CHECKED_IN', 'COMPLETED'));
-- BR-054 / ADR-023: one PENDING hold per anonymous browser per clinic.
CREATE UNIQUE INDEX "appointment_one_hold_per_client" ON "appointment" ("clinic_id", "hold_client_hash") WHERE status = 'PENDING';
CREATE INDEX "appointment_pending_expiry_idx" ON "appointment" ("hold_expires_at") WHERE status = 'PENDING';

-- ADR-016 layer 3: only SRS 9.1 transitions AT-01..AT-11 are possible, whatever the code path.
CREATE FUNCTION appointment_status_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status AND NOT (
       (OLD.status = 'PENDING'    AND NEW.status IN ('CONFIRMED', 'EXPIRED', 'CANCELLED'))
    OR (OLD.status = 'CONFIRMED'  AND NEW.status IN ('CHECKED_IN', 'CANCELLED', 'NO_SHOW'))
    OR (OLD.status = 'CHECKED_IN' AND NEW.status IN ('COMPLETED', 'CANCELLED'))
  ) THEN
    RAISE EXCEPTION 'invalid appointment transition % -> %', OLD.status, NEW.status USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER "appointment_status_guard" BEFORE UPDATE OF status ON "appointment"
  FOR EACH ROW EXECUTE FUNCTION appointment_status_guard();

-- public_access_token (Arch 11.16, 12.3)
ALTER TABLE "public_access_token" ADD CONSTRAINT "public_access_token_binding_check" CHECK (
     (purpose = 'BOOKING' AND appointment_id IS NOT NULL AND queue_entry_id IS NULL)
  OR (purpose = 'QUEUE'   AND queue_entry_id IS NOT NULL AND appointment_id IS NULL)
  OR (purpose = 'DISPLAY' AND appointment_id IS NULL AND queue_entry_id IS NULL));
ALTER TABLE "public_access_token" ADD CONSTRAINT "public_access_token_expiry_check" CHECK (purpose = 'DISPLAY' OR expires_at IS NOT NULL);
CREATE UNIQUE INDEX "public_access_token_one_booking" ON "public_access_token" ("appointment_id") WHERE purpose = 'BOOKING' AND revoked_at IS NULL;
CREATE UNIQUE INDEX "public_access_token_one_queue" ON "public_access_token" ("queue_entry_id") WHERE purpose = 'QUEUE' AND revoked_at IS NULL;

-- idempotency_record (Arch 11.19)
ALTER TABLE "idempotency_record" ADD CONSTRAINT "idempotency_record_completed_check" CHECK (state = 'IN_PROGRESS' OR (response_status IS NOT NULL AND response_body_enc IS NOT NULL));

GRANT USAGE ON TYPE appointment_channel, appointment_status, cancel_actor, access_token_purpose, idempotency_state, patient_source TO sc_app;
GRANT SELECT, INSERT, UPDATE, DELETE ON "appointment", "public_access_token", "idempotency_record" TO sc_app;
GRANT ALL ON "appointment", "public_access_token", "idempotency_record" TO sc_owner;
